    window.__G = 5.50; window.__H = 'Y'; BALLS.X.beta = 0.4; BALLS.Y.beta = 2 / 3;
    modelRun = (0, eval)('(' + modelRun.toString().replace('curG()', "(planet==='earth'?G_EARTH:__G)") + ')');
